const wordCount = (text) =>
  (text?.match(/[A-Za-z0-9]+(?:['’][A-Za-z0-9]+)*/g) ?? []).length

function normalizeRawItem(level, raw, index) {
  const [type, topic, audio, question, questionJa, choiceTexts, answerIndex, explain, visual = ''] = raw
  const choices = choiceTexts.map((text, choiceIndex) =>
    Object.freeze({
      id: String.fromCharCode(97 + choiceIndex),
      text,
    }),
  )
  const meta = LISTENING_TYPE_META[type]
  const spokenTail = meta?.spokenChoices ? choiceTexts.join(' ') : question
  const stimulus = [...audio.map((segment) => segment[1]), spokenTail].join(' ')
  return Object.freeze({
    id: `listen_${level}_${String(index + 1).padStart(2, '0')}`,
    level,
    type,
    topic,
    audio: Object.freeze(
      audio.map(([speaker, text]) => Object.freeze({ speaker, text })),
    ),
    question,
    questionJa,
    choices: Object.freeze(choices),
    answer: choices[answerIndex]?.id,
    explain,
    visual,
    wordCount: wordCount(stimulus),
    plays: LISTENING_PROFILES[level]?.plays[type] ?? 1,
  })
}

export const LISTENING_ITEMS = Object.freeze(
  Object.entries(RAW_ITEMS).flatMap(([level, items]) =>
    items.map((raw, index) => normalizeRawItem(level, raw, index)),
  ),
)

export const LISTENING_BY_ID = Object.freeze(
  Object.fromEntries(LISTENING_ITEMS.map((item) => [item.id, item])),
)

export const getListeningItem = (id) => LISTENING_BY_ID[id]

export const listeningByLevel = (levelId) =>
  LISTENING_ITEMS.filter((item) => item.level === levelId)

export function listeningSpokenSegments(item) {
  if (!item) return []
  const segments = [...item.audio]
  if (LISTENING_TYPE_META[item.type]?.spokenChoices) {
    item.choices.forEach((choice, index) => {
      segments.push({
        speaker: 'N',
        text: `Number ${index + 1}. ${choice.text}`,
      })
    })
  } else {
    segments.push({ speaker: 'Q', text: item.question })
  }
  return segments
}

function shuffled(items, rng = Math.random) {
  const out = [...items]
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1))
    ;[out[i], out[j]] = [out[j], out[i]]
  }
  return out
}

export function shuffledListeningChoices(item, rng = Math.random) {
  // 音声で Number 1... と読み上げる形式は放送どおり3件なので、そのまま並べる。
  if (LISTENING_TYPE_META[item?.type]?.spokenChoices) return [...(item?.choices ?? [])]
  // 画面に出す形式は4択の教材から「3択＋わからない」に絞る。
  const choices = limitQuizChoices(
    item?.choices ?? [],
    (choice) => choice.id === item?.answer,
    { seed: item?.id ?? '' },
  )
  return shuffled(choices, rng)
}

export function buildListeningDeck(
  source = { type: 'level', levelId: '5' },
  { size = 10, rng = Math.random } = {},
) {
  if (source.type === 'listeningList') {
    const reviewItems = (source.ids ?? []).map(getListeningItem).filter(Boolean)
    const deck = source.preserveOrder ? reviewItems : shuffled(reviewItems, rng)
    return size ? deck.slice(0, size) : deck
  }

  const levelId = source.levelId ?? '5'
  const candidates = listeningByLevel(levelId)
  if (!size || size >= candidates.length) return shuffled(candidates, rng)

  // 10問版でも、級の出題形式が偶然欠落しないよう公式構成比を縮約して層化抽出する。
  const profile = LISTENING_PROFILES[levelId]
  const targets = Object.entries(profile?.typeTargets ?? {})
  const targetTotal = targets.reduce((sum, [, target]) => sum + target, 0)
  const quotas = Object.fromEntries(
    targets.map(([type, target]) => [type, Math.floor((size * target) / targetTotal)]),
  )
  let allocated = Object.values(quotas).reduce((sum, quota) => sum + quota, 0)
  while (allocated < size) {
    const nextType = targets
      .map(([type, target]) => ({
        type,
        gap: (size * target) / targetTotal - quotas[type],
        capacity: candidates.filter((item) => item.type === type).length - quotas[type],
      }))
      .filter(({ capacity }) => capacity > 0)
      .sort((a, b) => b.gap - a.gap)[0]?.type
    if (!nextType) break
    quotas[nextType] += 1
    allocated += 1
  }

  const deck = targets.flatMap(([type]) =>
    shuffled(candidates.filter((item) => item.type === type), rng).slice(0, quotas[type]),
  )
  return shuffled(deck, rng)
}
